source.searchUrl:
@js:var base = 'https://m.dzrjk.com';
var kw = String(key);
var page = base + '/user/search.html?q=' + encodeURIComponent(kw);
var html = String(java.ajax(page));
if (html.length < 500) html = String(java.ajax(page));
var names = 'vw abw ru jrt van fw cwl gpr uyoo tz euu tsn eju um fp dvm jpk deblkx ht azy sna wqx fpp rup jwj bgt qp yf cw wq'.split(' ');
var re = /var\s+([A-Za-z_]\w*)\s*=\s*"([^"]*)"/g;
var map = {};
var mm;
while ((mm = re.exec(html)) !== null) { map[mm[1]] = mm[2]; }
var pairs = [];
for (var i = 0; i < names.length; i++) {
    var n = names[i];
    var v = map[n];
    if (typeof v === 'undefined') continue;
    if (n === 'bgt' && v.length > 1) v = v.slice(0, v.length - 1);
    pairs.push(n + '=' + encodeURIComponent(v));
}
pairs.push('sign=' + encodeURIComponent(map['sign'] || ''));
pairs.push('q=' + encodeURIComponent(kw));
var opt = {
    method: 'POST',
    body: pairs.join('&'),
    headers: {
        'X-Requested-With': 'XMLHttpRequest',
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
        'Origin': base,
        'Referer': page
    }
};
base + '/api/search,' + JSON.stringify(opt)

